def convert_durations(seconds_list):
    def format_duration(s):
        hours = s // 3600
        remainder = s % 3600
        minutes = remainder // 60
        secs = remainder % 60
        parts = []
        if hours:
            parts.append(f"{hours} hour{'s' if hours != 1 else ''}")
        if minutes and (hours == 0):
            parts.append(f"{minutes} minute{'s' if minutes != 1 else ''}")
        if secs and (hours == 0 and minutes == 0):
            parts.append(f"{secs} second{'s' if secs != 1 else ''}")
        if not parts:
            parts.append(f"{s} second{'s' if s != 1 else ''}")
        return ' '.join(parts)

    return [format_duration(x) for x in seconds_list]

