// [typeCheck] Type-safe function with strict typing and validation
function countOccurrences(arr: number[], target: number): Result | Error {
    // [emptyArrayCheck] Validate the array is not empty
    if (Array.isArray(arr) && arr.length === 0) {
        throw new Error("Error: The array is empty.");
    }

    // [notANumberCheck] Validate that target is a number (exclude boolean)
    if (typeof target !== 'number' || typeof target === 'boolean') {
        throw new Error("Error: The target must be a number.");
    }

    if (!Array.isArray(arr)) {
        throw new Error("Error: First argument must be an array.");
    }

    let count = 0;
    for (const num of arr) {
        if (num === target) count++;
    }

    return count === 0 ? "The number is not present in the array." : count;
}

// Define a simple Result type for successful outputs
