"function maxConsecutiveSum(arr, k) {
    if (arr.length < k) return 0;
    let currentSum = 0;
    let maxSum = Number.NEGATIVE_INFINITY;
    for (let i = 0; i <= arr.length - k; i++) {
        currentSum += arr[i];
        if (i === arr.length - k) {
            currentSum -= arr[i - (arr.length - k)];
        }
        maxSum = Math.max(maxSum, currentSum);
