    if total == 0:
        return {
            "total_patients": 0,
            "average_age": 0,
            "diagnosis_count": {},
            "unique_medications": []
        }
    total_age = sum(p["age"] for p in patients)
    average_age = total_age / total
    diagnosis_count = {}
    all_meds = set()
    for patient in patients:
        diagnosis = patient["diagnosis"]
        diagnosis_count[diagnosis] = diagnosis_count.get(diagnosis, 0) + 1
        for med in patient["medications"]:
            all_meds.add(med)
    unique_meds = sorted(all_meds)
    return {
        "total_patients": total,
        "average_age": float(average_age),
        "diagnosis_count": diagnosis_count,
        "unique_medications": unique_meds
    }
