def analyze_patient_data(patient_list):
    n = len(patient_list)
    if n == 0:
        return {
            "total_patients": 0,
            "average_age": 0.0,
            "diagnosis_count": {},
            "unique_medications": []
        }
    avg_age = sum(p["age"] for p in patient_list) / n
    diagnosis_freq = {}
    meds_set = set()
    for p in patient_list:
        d = p["diagnosis"]
        diagnosis_freq[d] = diagnosis_freq.get(d, 0) + 1
        meds_set.update(p["medications"])
    unique_meds = sorted(meds_set)
    return {
        "total_patients": n,
        "average_age": float(avg_age),
        "diagnosis_count": diagnosis_freq,
        "unique_medications": unique_meds
    }

